{"version":3,"file":"field-contract.js","sourceRoot":"","sources":["../../../source/pigment-rivers/field-contract.ts"],"names":[],"mappings":"AAAA,uFAAuF;AACvF,MAAM,CAAC,MAAM,QAAQ,GAAG,kCAAkC,CAAC;AAC3D,MAAM,CAAC,MAAM,eAAe,GAAG,CAAC,OAAO,EAAE,MAAM,EAAE,MAAM,EAAE,MAAM,CAAU,CAAC;AAE1E,MAAM,UAAU,SAAS,CACvB,IAA6H,EAC7H,GAAW,EACX,IAAuB;IAEvB,IAAI,IAAI,CAAC,OAAO,KAAK,CAAC,IAAI,IAAI,CAAC,GAAG,KAAK,GAAG,IAAI,MAAM,CAAC,IAAI,CAAC,IAAI,CAAC,SAAS,CAAC,CAAC,MAAM,KAAK,CAAC,IAAI,OAAO,IAAI,CAAC,SAAS,CAAC,OAAO,KAAK,QAAQ,EAAE,CAAC;QACrI,MAAM,KAAK,CAAC,2BAA2B,GAAG,4BAA4B,CAAC,CAAC;IAC1E,CAAC;IACD,IAAI,MAAM,CAAC,IAAI,CAAC,IAAI,CAAC,MAAM,CAAC,CAAC,MAAM,KAAK,IAAI,CAAC,MAAM,IAAI,IAAI,CAAC,IAAI,CAAC,GAAG,CAAC,EAAE,CAAC,CAAC,MAAM,CAAC,QAAQ,CAAC,IAAI,CAAC,MAAM,CAAC,GAAG,CAAC,CAAC,CAAC,EAAE,CAAC;QAC5G,MAAM,KAAK,CAAC,kBAAkB,GAAG,4CAA4C,CAAC,CAAC;IACjF,CAAC;IACD,OAAO,IAAI,CAAC;AACd,CAAC","sourcesContent":["// New scene-local ABI. Reuses LoRegion's local frame to consume existing paint fields.
export const BAND_ABI = 'examples/folded-pigment-bands/v1';
export const BAND_VALUE_KEYS = ['scale', 'fold', 'flow', 'seed'] as const;

export function readField(
  data: { version: number; abi: string; fragments: Readonly<Record<string, string>>; values: Readonly<Record<string, number>> },
  abi: string,
  keys: readonly string[],
) {
  if (data.version !== 1 || data.abi !== abi || Object.keys(data.fragments).length !== 1 || typeof data.fragments.helpers !== 'string') {
    throw Error(`Pigment Rivers requires ${abi} with one helpers fragment`);
  }
  if (Object.keys(data.values).length !== keys.length || keys.some(key => !Number.isFinite(data.values[key]))) {
    throw Error(`Pigment Rivers ${abi} values do not match its declared contract`);
  }
  return data;
}
"]}

